import java.util.Scanner;
public class JCheckAge2 {
	public static void main(String[] args) {
		JCheckAge2 jca = new JCheckAge2();
		jca.checkAge();
	}
	// Khatwa 1: Tareef al-tariqa allati taamel ala silsilat al-mudkhal
	public void checkAge() {
		// Khatwa 1.1: Talab madkhal sahi7 ma damaa lam yutamm mu3alajatuh; wa itha tam, tawqaf
		Scanner scan = new Scanner(System.in);
		boolean processed = false;
		while ( ! processed ) {
			System.out.println("Adkhil al-ism wa al-umr, mufassalan bi faasil:");
			String s = scan.next();
			// Khatwa 1.1.1: Qassim al-string al-mu'ta ila al-ism wal-umr
			String[] lst = s.split(":");
			// Khatwa 1.1.2: Ahdif al-kod alladhi qad yarmee istiathna fi qita try
			try {
				String name = lst[0];
				int age = Integer.parseInt(lst[1]);
				if ( age >= 13 && age <= 19 ) {           
					System.out.println(name + " is a teenager.");
				} else {          
					System.out.println(name + " is not a teenager.");
				}
	            processed = true;
			}
			// Khatwa 1.1.3: Ta'amal ma'a jami' al-istaithna'at al-mumkina allati qad turmee fi qita try
			catch ( ArrayIndexOutOfBoundsException ex ) {
				System.out.println("Khata! Afsel al-ism wal-umr bi faasil.");
			} catch ( NumberFormatException ex) {
				System.out.println("Khata! al-umr yajib an yakun adad sahih.");
			}
		}	
	}
}
